import{_ as h,o as n,c,a2 as d}from"./chunks/framework.62rcL0wY.js";const u=JSON.parse('{"title":"Lệnh ẩn và lệnh không có tài liệu","description":"","frontmatter":{},"headers":[],"relativePath":"phu-luc/lenh-an.md","filePath":"phu-luc/lenh-an.md"}'),e={name:"phu-luc/lenh-an.md"};function a(r,t,o,i,g,l){return n(),c("div",null,[...t[0]||(t[0]=[d('<h1 id="lenh-an-va-lenh-khong-co-tai-lieu" tabindex="-1">Lệnh ẩn và lệnh không có tài liệu <a class="header-anchor" href="#lenh-an-va-lenh-khong-co-tai-lieu" aria-label="Permalink to &quot;Lệnh ẩn và lệnh không có tài liệu&quot;">​</a></h1><p>Trang này liệt kê các từ khóa đặc biệt của Clickermann v4.13: 6 lệnh bị ẩn trong chú thích HTML của tệp <code>help.chm</code>, 5 từ khóa có trong tệp <code>data/keywords.txt</code> của chương trình nhưng không có mục hướng dẫn riêng trong help, và 2 từ khóa xuất hiện trong phần Lịch sử phiên bản của help.</p><h2 id="sau-lenh-bi-an-trong-ma-nguon-html-cua-help" tabindex="-1">Sáu lệnh bị ẩn trong mã nguồn HTML của help <a class="header-anchor" href="#sau-lenh-bi-an-trong-ma-nguon-html-cua-help" aria-label="Permalink to &quot;Sáu lệnh bị ẩn trong mã nguồn HTML của help&quot;">​</a></h2><p>Khi kiểm tra mã nguồn các trang trong <code>help.chm</code> (mục Làm việc với số, mục Chuỗi và tệp, mục Script và plugin), có 6 mục lệnh đã bị đóng trong cặp thẻ chú thích <code>&lt;!-- ... --&gt;</code> nên người đọc help thông thường không nhìn thấy.</p><table tabindex="0"><thead><tr><th>Lệnh</th><th>Nơi xuất hiện trong nguồn</th><th>Ghi chú</th></tr></thead><tbody><tr><td><code>NUM</code></td><td>help, mục Làm việc với số (ẩn trong chú thích HTML)</td><td>Bị ẩn trong help, chưa rõ còn chạy không.</td></tr><tr><td><code>STR</code></td><td>help, mục Chuỗi và tệp (ẩn trong chú thích HTML)</td><td>Bị ẩn trong help, chưa rõ còn chạy không.</td></tr><tr><td><code>ADDR</code></td><td>help, mục Làm việc với số (ẩn trong chú thích HTML)</td><td>Bị ẩn trong help, chưa rõ còn chạy không.</td></tr><tr><td><code>FROMADDR</code></td><td>help, mục Làm việc với số (ẩn trong chú thích HTML)</td><td>Bị ẩn trong help, chưa rõ còn chạy không.</td></tr><tr><td><code>TOADDR</code></td><td>help, mục Làm việc với số (ẩn trong chú thích HTML)</td><td>Bị ẩn trong help, chưa rõ còn chạy không.</td></tr><tr><td><code>LOAD</code></td><td>help, mục Script và plugin (ẩn trong chú thích HTML) và Lịch sử phiên bản</td><td>Bị ẩn trong help, chưa rõ còn chạy không (Lịch sử phiên bản mục v4.12.001 ghi đã gỡ bỏ lệnh <code>LOAD</code>).</td></tr></tbody></table><hr><h2 id="nam-tu-khoa-co-trong-tep-data-keywords-txt-nhung-khong-co-muc-tra-cuu-rieng" tabindex="-1">Năm từ khóa có trong tệp <code>data/keywords.txt</code> nhưng không có mục tra cứu riêng <a class="header-anchor" href="#nam-tu-khoa-co-trong-tep-data-keywords-txt-nhung-khong-co-muc-tra-cuu-rieng" aria-label="Permalink to &quot;Năm từ khóa có trong tệp `data/keywords.txt` nhưng không có mục tra cứu riêng&quot;">​</a></h2><p>Tệp <code>data/keywords.txt</code> của chương trình (danh sách từ khóa để trình soạn thảo tô màu) còn chứa 5 từ khóa dưới đây nhưng cả <code>help.chm</code> lẫn sách của Chô tô đều không có mục tra cứu riêng cho chúng:</p><table tabindex="0"><thead><tr><th>Từ khóa</th><th>Nơi xuất hiện trong nguồn</th><th>Ghi chú</th></tr></thead><tbody><tr><td><code>GOSUB</code></td><td><code>data/keywords.txt</code>, help (Lịch sử phiên bản v4.1.000), script mẫu đi kèm chương trình</td><td>Không có mục tra cứu riêng trong help, chưa rõ còn chạy không.</td></tr><tr><td><code>IF_KEYDOWN</code></td><td><code>data/keywords.txt</code>, help (Lịch sử phiên bản v3.2 beta)</td><td>Không có mục tra cứu riêng trong help, chưa rõ còn chạy không.</td></tr><tr><td><code>IF_TIME</code></td><td><code>data/keywords.txt</code>, help (Lịch sử phiên bản v3.1 beta, v4.0.002)</td><td>Không có mục tra cứu riêng trong help, chưa rõ còn chạy không.</td></tr><tr><td><code>HTTPPOST</code></td><td><code>data/keywords.txt</code></td><td>Không có tài liệu mô tả trong help, chưa rõ còn chạy không.</td></tr><tr><td><code>TRAYSAY</code></td><td><code>data/keywords.txt</code></td><td>Không có tài liệu mô tả trong help, chưa rõ còn chạy không.</td></tr></tbody></table><hr><h2 id="hai-tu-khoa-xuat-hien-trong-lich-su-phien-ban" tabindex="-1">Hai từ khóa xuất hiện trong Lịch sử phiên bản <a class="header-anchor" href="#hai-tu-khoa-xuat-hien-trong-lich-su-phien-ban" aria-label="Permalink to &quot;Hai từ khóa xuất hiện trong Lịch sử phiên bản&quot;">​</a></h2><p>Ngoài hai nhóm trên, trong <a href="/clickermann-guide-vi/phu-luc/lich-su.html">Lịch sử phiên bản</a> còn nhắc tới:</p><table tabindex="0"><thead><tr><th>Từ khóa</th><th>Nơi xuất hiện trong nguồn</th><th>Ghi chú</th></tr></thead><tbody><tr><td><code>BREAK</code></td><td><code>data/keywords.txt</code>, help (Lịch sử phiên bản v4.0.002)</td><td>Không có mục tra cứu riêng trong help (mục Cấu trúc lệnh), chưa rõ còn chạy không.</td></tr><tr><td><code>$_line</code></td><td>Help (Lịch sử phiên bản v3.2 beta), script mẫu đi kèm chương trình</td><td>Không có trong bảng biến hệ thống của help (phần Giới thiệu ngôn ngữ), chưa rõ còn chạy không.</td></tr></tbody></table>',13)])])}const m=h(e,[["render",a]]);export{u as __pageData,m as default};
